fun {n m} {matType} [Mathlib.Tactic.Linarith.SimplexAlgorithm.UsableInSimplexAlgorithm matType] =>
  have free := #[];
  have basic := #[];
  have row := 0;
  have col := 0;
  do
  let __s ←
    forIn { } (free, basic, row, col) fun x __s =>
        have free := __s.1;
        have __s := __s.2;
        have basic := __s.1;
        have __s := __s.2;
        have row := __s.1;
        have col := __s.2;
        if (decide (row < n) && decide (col < m)) = true then do
          liftM
              (Lean.checkSystem
                `Mathlib.Tactic.Linarith.SimplexAlgorithm.Gauss.getTableauImp.toString)
          let __do_lift ← Mathlib.Tactic.Linarith.SimplexAlgorithm.Gauss.findNonzeroRow row col
          match __do_lift with
            | none =>
              have free := free.push col;
              have col := col + 1;
              pure (ForInStep.yield (free, basic, row, col))
            | some rowToSwap => do
              modify fun mat => Mathlib.Tactic.Linarith.SimplexAlgorithm.swapRows mat row rowToSwap
              modify fun mat =>
                  Mathlib.Tactic.Linarith.SimplexAlgorithm.divideRow mat row mat[(row, col)]!
              forIn [:n] PUnit.unit fun i __s =>
                  if (i == row) = true then pure (ForInStep.yield PUnit.unit)
                  else do
                    let __do_lift ← get
                    have coef : ℚ := __do_lift[(i, col)]!
                    if (coef != 0) = true then do
                        modify fun mat =>
                            Mathlib.Tactic.Linarith.SimplexAlgorithm.subtractRow mat row i coef
                        pure (ForInStep.yield PUnit.unit)
                      else pure (ForInStep.yield PUnit.unit)
              have basic : Array ℕ := basic.push col
              have row : ℕ := row + 1
              have col : ℕ := col + 1
              pure (ForInStep.yield (free, basic, row, col))
        else pure (ForInStep.done (free, basic, row, col))
  have free : Array ℕ := __s.1
  have __s : Array ℕ × ℕ × ℕ := __s.2
  have basic : Array ℕ := __s.1
  have __s : ℕ × ℕ := __s.2
  have row : ℕ := __s.1
  have col : ℕ := __s.2
  let __s ←
    forIn [col:m] free fun i __s =>
        have free := __s;
        have free := free.push i;
        pure (ForInStep.yield free)
  have free : Array ℕ := __s
  let __do_lift ← get
  have vals : List (ℕ × ℕ × ℚ) :=
    List.filterMap
      (fun x =>
        match x with
        | (i, j, v) =>
          if (j == basic[i]!) = true then none
          else some (i, (Array.findIdx? (fun x => x == j) free).get!, -v))
      (Mathlib.Tactic.Linarith.SimplexAlgorithm.getValues __do_lift)
  let ansMatrix ← pure (Mathlib.Tactic.Linarith.SimplexAlgorithm.ofValues vals)
  pure { basic := basic, free := free, mat := ansMatrix }

